test('remembered contact IDs alone do not exempt a wall miss; exemption survives cleared memory', () => {
  const w = setup(),
    b = shot(w, { x: 416 });
  b.hit.add(123);
  tick(w, b);
  expect(misses(w)).toEqual([1, 0]);
  const exempt = shot(w, { x: 416, missExempt: true });
  exempt.hit.clear();
  tick(w, exempt);
  expect(exempt.dead).toBe(true);
  expect(misses(w)).toEqual([1, 0]);
});

